SELECT CASE WHEN location IN ('London', 'Chiang Mai') THEN 'tier_1' ELSE 'other' END AS location_group, SUM(budget) AS total_budget, ROUND((100 * SUM(CASE WHEN location = 'London' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_london, SUM(CASE WHEN dept_name = 'Sales' THEN 1 ELSE 0 END) AS sales_count FROM departments WHERE location = 'London' GROUP BY location_group HAVING sales_count < 56;
